def merge_sort(items):
    if len(items) < 2:
        return list(items)
    mid = len(items) // 2
    left, right = merge_sort(items[:mid]), merge_sort(items[mid:])
    out, i, j = [], 0, 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            out.append(left[i]); i += 1
        else:
            out.append(right[j]); j += 1
    return out + left[i:] + right[j:]

assert merge_sort([3, 1, 2, 1]) == [1, 1, 2, 3]

def partition(a, lo, hi):
    """Move a[hi] to its final index p: a[lo:p] < pivot <= a[p+1:hi+1]."""
    pivot = a[hi]
    p = lo
    for i in range(lo, hi):
        if a[i] < pivot:
            a[i], a[p] = a[p], a[i]
            p += 1
    a[p], a[hi] = a[hi], a[p]
    return p

def quickselect(a, k):
    """Return the k-th smallest value (0-based). Reorders a."""
    lo, hi = 0, len(a) - 1
    while True:
        p = partition(a, lo, hi)
        if p == k:
            return a[p]
        if k < p:
            hi = p - 1
        else:
            lo = p + 1

scores = [42, 7, 19, 88, 3, 61, 25]
print(quickselect(scores[:], 3), sorted(scores)[3])

# Expected output:
# 25 25

