import random

def partition(a, lo, hi):
    """Move a[hi] to its final index p: a[lo:p] < pivot <= a[p+1:hi+1]."""
    pivot = a[hi]
    p = lo
    for i in range(lo, hi):
        if a[i] < pivot:
            a[i], a[p] = a[p], a[i]
            p += 1
    a[p], a[hi] = a[hi], a[p]
    return p

def k_smallest(values, k):
    if not 0 <= k <= len(values):
        raise ValueError("k out of range")
    if k == 0:
        return []
    a = list(values)
    lo, hi = 0, len(a) - 1
    while True:
        p = partition(a, lo, hi)
        if p == k - 1:
            return sorted(a[:k])
        if p < k - 1:
            lo = p + 1
        else:
            hi = p - 1

rng = random.Random(3)
for _ in range(200):
    values = [rng.randint(0, 20) for _ in range(rng.randint(1, 30))]
    k = rng.randint(0, len(values))
    assert k_smallest(values, k) == sorted(values)[:k]
print("k_smallest matches sorted on 200 random lists")

