class Trie:
    def __init__(self):
        self.root = {}

    def insert(self, word):
        node = self.root
        for ch in word:
            node = node.setdefault(ch, {})
        node["$"] = True  # end-of-word marker; the words here never contain "$"

    def starts_with(self, prefix):
        node = self.root
        for ch in prefix:
            if ch not in node:
                return []
            node = node[ch]
        found, stack = [], [(node, prefix)]
        while stack:
            node, text = stack.pop()
            for ch, child in node.items():
                if ch == "$":
                    found.append(text)
                else:
                    stack.append((child, text + ch))
        return sorted(found)

words = Trie()
for w in ["sort", "sorted", "sorting", "stack", "set"]:
    words.insert(w)
print(words.starts_with("sort"))
print(words.starts_with("st"), words.starts_with("x"))

# Expected output:
# ['sort', 'sorted', 'sorting']
# ['stack'] []

