class PrefixCounter:
    def __init__(self):
        self.root = {"count": 0, "children": {}}

    def add(self, word):
        node = self.root
        node["count"] += 1
        for ch in word:
            node = node["children"].setdefault(ch, {"count": 0, "children": {}})
            node["count"] += 1

    def count(self, prefix):
        node = self.root
        for ch in prefix:
            node = node["children"].get(ch)
            if node is None:
                return 0
        return node["count"]

counter = PrefixCounter()
for word in ["sort", "sorted", "sorting", "stack", "set"]:
    counter.add(word)
assert [counter.count(p) for p in ["", "s", "sort", "st", "x"]] == [5, 5, 3, 1, 0]
print(counter.count("sor"))

