class DisjointSet:
    def __init__(self, items):
        self.parent = {x: x for x in items}
        self.size = {x: 1 for x in items}

    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]  # path halving
            x = self.parent[x]
        return x

    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False
        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra
        self.parent[rb] = ra
        self.size[ra] += self.size[rb]
        return True

groups = DisjointSet("ABCDE")
print(groups.union("A", "B"), groups.union("C", "D"), groups.union("B", "A"))
print(groups.find("A") == groups.find("B"), groups.find("A") == groups.find("C"))
groups.union("B", "D")
print(len({groups.find(x) for x in "ABCDE"}))

# Expected output:
# True True False
# True False
# 2

