def kruskal(nodes, edges):
    groups = DisjointSet(nodes)
    chosen = [(w, a, b) for w, a, b in sorted(edges) if groups.union(a, b)]
    if len(chosen) != len(nodes) - 1:
        raise ValueError("graph is not connected")
    return chosen

